      "title": "科学家发布开源RNA序列基础模型",
      "summary": "首页 > 科研进展 近日，中国科学技术大学医学影像智能与机器人（MIRACLE）实验室 发布了一款开源RNA（核糖核酸）序列基础模型structRFM ，有效提高AI模型在RNA结构预测与功能推断一系列下游任务中的性能，有望助力人工智能驱动的科学研究、生物学机制理解、药物发现等。 RNA是重要的生物大分子，存在于生物细",
